CREATE DATABASE IF NOT EXISTS rangers_safety_systems CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE rangers_safety_systems;
CREATE TABLE admins(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,slug VARCHAR(190) NOT NULL UNIQUE,description TEXT,image_path VARCHAR(500),status ENUM('active','inactive') DEFAULT 'active',display_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id BIGINT UNSIGNED NOT NULL,name VARCHAR(255) NOT NULL,slug VARCHAR(255) NOT NULL UNIQUE,short_description TEXT,full_description MEDIUMTEXT,specifications JSON,main_image_id BIGINT UNSIGNED NULL,status ENUM('active','inactive') DEFAULT 'inactive',display_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE product_images(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,image_path VARCHAR(500) NOT NULL,alt_text VARCHAR(255),display_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
ALTER TABLE products ADD CONSTRAINT fk_main_image FOREIGN KEY(main_image_id) REFERENCES product_images(id) ON DELETE SET NULL;
CREATE TABLE exhibitions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,description TEXT,image_path VARCHAR(500),status ENUM('active','inactive') DEFAULT 'active',display_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE exhibition_products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,exhibition_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,display_order INT DEFAULT 0,UNIQUE(exhibition_id,product_id),FOREIGN KEY(exhibition_id) REFERENCES exhibitions(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE booklet_settings(id INT PRIMARY KEY,title VARCHAR(255),description TEXT,status ENUM('active','inactive') DEFAULT 'active',updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE booklet_products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL UNIQUE,display_order INT DEFAULT 0,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE company_information(id INT PRIMARY KEY,company_name VARCHAR(255),about_heading VARCHAR(255),about_description MEDIUMTEXT,company_image VARCHAR(500),updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE website_settings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(100) NOT NULL UNIQUE,setting_value TEXT,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE social_links(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,platform VARCHAR(40) NOT NULL UNIQUE,url VARCHAR(1000),status ENUM('active','inactive') DEFAULT 'inactive',updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE media_library(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,filename VARCHAR(255) NOT NULL,file_path VARCHAR(500) NOT NULL,mime_type VARCHAR(100) NOT NULL,file_size BIGINT UNSIGNED NOT NULL,uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE login_attempts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ip_hash CHAR(64) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(ip_hash,created_at));
