-- Editable CMS pages and page elements (import cms_migration.sql on existing installs)
CREATE TABLE cms_pages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,slug VARCHAR(100) NOT NULL UNIQUE,title VARCHAR(200) NOT NULL,status ENUM('active','inactive') DEFAULT 'active',sort_order INT DEFAULT 0,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE cms_elements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,page_slug VARCHAR(100) NOT NULL,element_key VARCHAR(255) NOT NULL,kind ENUM('text','image','video','link','html','style') NOT NULL DEFAULT 'text',content MEDIUMTEXT NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY unique_element(page_slug,element_key));
